// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool, IStolenNftOracle} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    TinyNft nft;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
        nft = new TinyNft();
    }

    // stubs consumed by C through the addresses it was given
    function protocolFeeRate() external pure returns (uint16) {
        return 0;
    }

    function ownerOf(uint256) external view returns (address) {
        return address(this);
    }

    function testFuzz_property(uint256 x, uint256 y, uint256 tokenId) public {
        // admissible domain: reserves large enough that the quoted payout is >= 1 wei
        uint128 vnr = uint128(bound(y, 1e18, 1e30));
        uint128 vbr = uint128(bound(x, vnr / 1e18 + 2, type(uint128).max - 1));
        tokenId = bound(tokenId, 0, type(uint256).max - 1);

        nft.mint(address(this), tokenId);

        c.initialize(address(0), address(nft), vbr, vnr, 0, 0, bytes32(0), false, false);

        uint256[] memory ids = new uint256[](1);
        ids[0] = tokenId;
        uint256[] memory weights = new uint256[](1);
        weights[0] = 1e18;
        PrivatePool.MerkleMultiProof memory proof;
        IStolenNftOracle.Message[] memory msgs = new IStolenNftOracle.Message[](0);

        // fund the pool so it can pay out the sale proceeds in ETH
        vm.deal(address(c), type(uint128).max);

        uint256 before = c.virtualBaseTokenReserves();
        bool ok;
        try c.sell(ids, weights, proof, msgs) {
            ok = true;
        } catch {
            ok = false;
        }

        // RULE: a completed sale strictly reduces the pool's virtual base reserves.
        assertTrue(ok && c.virtualBaseTokenReserves() < before);
    }

    receive() external payable {}
}

contract TinyNft {
    mapping(uint256 => address) public ownerOf;

    function mint(address to, uint256 id) external {
        ownerOf[id] = to;
    }

    function balanceOf(address a) external view returns (uint256) {
        return a == ownerOf[0] ? 1 : 0;
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        require(ownerOf[id] == from, "WRONG_FROM");
        ownerOf[id] = to;
    }
}
